select

from corgi_order o

    left join corgi_merchandise m on m.merch_code = o.merch_id

where 1=1

    and o.user_id = #{order.userId}


    and o.market_id = #{order.marketId}


    and o.trade_no = #{order.tradeNo}


    and o.pay_amount = #{order.payAmount}


    and o.pay_type = #{order.payType}


    and o.pay_type != 'withdraw'


    and o.seller_id != #{order.userId}


    and o.status = #{order.status}


    and m.type = #{order.merchType}

order by o.id desc
limit #{start}, #{size}

