select `user_id` userId, `goods_type` goodsType, `merch_id` merchId, `goods_id` goodsId, price, currency, trader_id traderId, trade_no traderNo, `desc` `status`, ctime, uptime from corgi_user_goods where goods_type = #{goods.goodsType} and goods_id = #{goods.goodsId} and trader_id = #{goods.traderId} and status = '1'
